los parámetros comerciales u operativos de Beneficios LF deben resolverse desde configuración gobernada y no desde literales de frontend, mockups o lógica específica de una pantalla. Tasas, topes, frecuencias, ciclos de refresco, multiplicadores, participaciones por referido y demás valores variables permanecen configurables. Esta regla no crea todavía una tabla o módulo de configuración: la persistencia especializada se definirá reutilizando estructuras canónicas cuando el dominio y su módulo estén formalizados. Referencias literales del contrato fuente: {\"decision_adr\":\"ADR-LF-BEN-001\",\"applicability_v1\":{\"all\":[],\"any\":[{\"op\":\"IN\",\"path\":[\"target\",\"screen\",\"id\"],\"values\":[5]}],\"status\":\"ACTIVE\",\"provenance\":{\"authority\":\"OWNER_AUTHORIZED_GOVERNED_MIGRATION\",\"r14_event_id\":19951,\"migration_source\":\"LEGACY_POSITIVE_BINDINGS_FOR_EQUIVALENCE_ONLY\",\"decision_event_id\":19948,\"migration_version\":\"20261002173000\"},\"consumer_roles\":[\"INPUT_GOVERNANCE\"],\"schema_version\":\"lf-rule-applicability/v1\"},\"new_table_authorized\":false,\"configurable_families\":[\"ENABLED\",\"DISCOUNT_RATE\",\"USER_CAP\",\"PERIOD_CAP\",\"REPORT_REFRESH_CYCLE\",\"RAFFLE_FREQUENCY\",\"PRIZE_CAP\",\"PRIZE_MULTIPLIER\",\"REFERRAL_ENTRIES\",\"REFERRAL_CAP\"],\"hardcoded_enabled_state\":\"DENY\",\"hardcoded_variable_values\":\"DENY\",\"specialized_persistence_status\":\"PENDING_CANONICAL_PRODUCT_MODULE\",\"frontend_as_configuration_authority\":false}. Binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/594","solicitante":"Cristhian / Claude S22-AJ"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"aj_home_benefit_configuration"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"aj_enabled_hardcoded"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"aj_variable_hardcoded"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_frontend_mockup_authoritative"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_ungoverned_config"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_unauthorized_new_table"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_specialized_persistence_assumed"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"aj_enabled_hardcoded":false,"aj_variable_hardcoded":false,"aj_frontend_mockup_authoritative":false,"aj_ungoverned_config":false,"aj_unauthorized_new_table":false,"aj_specialized_persistence_assumed":false,"aj_home_benefit_configuration":true},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"aj_enabled_hardcoded":true,"aj_variable_hardcoded":false,"aj_frontend_mockup_authoritative":false,"aj_ungoverned_config":false,"aj_unauthorized_new_table":false,"aj_specialized_persistence_assumed":false,"aj_home_benefit_configuration":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_enabled_hardcoded":false,"aj_variable_hardcoded":true,"aj_frontend_mockup_authoritative":false,"aj_ungoverned_config":false,"aj_unauthorized_new_table":false,"aj_specialized_persistence_assumed":false,"aj_home_benefit_configuration":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_enabled_hardcoded":false,"aj_variable_hardcoded":false,"aj_frontend_mockup_authoritative":true,"aj_ungoverned_config":false,"aj_unauthorized_new_table":false,"aj_specialized_persistence_assumed":false,"aj_home_benefit_configuration":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_enabled_hardcoded":false,"aj_variable_hardcoded":false,"aj_frontend_mockup_authoritative":false,"aj_ungoverned_config":true,"aj_unauthorized_new_table":false,"aj_specialized_persistence_assumed":false,"aj_home_benefit_configuration":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_enabled_hardcoded":false,"aj_variable_hardcoded":false,"aj_frontend_mockup_authoritative":false,"aj_ungoverned_config":false,"aj_unauthorized_new_table":true,"aj_specialized_persistence_assumed":false,"aj_home_benefit_configuration":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_enabled_hardcoded":false,"aj_variable_hardcoded":false,"aj_frontend_mockup_authoritative":false,"aj_ungoverned_config":false,"aj_unauthorized_new_table":false,"aj_specialized_persistence_assumed":true,"aj_home_benefit_configuration":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"aj_enabled_hardcoded":true,"aj_variable_hardcoded":true,"aj_frontend_mockup_authoritative":true,"aj_ungoverned_config":true,"aj_unauthorized_new_table":true,"aj_specialized_persistence_assumed":true,"aj_home_benefit_configuration":false},"esperado":false}]},"hash_paquete":"1914dbe747b04f3798945b39483a662cf720f2a4eff5611f9a4b1709a23c2a0e","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AJ-595-1","legacy_id":595,"relacionadas":[],"coberturas":[{"legacy_id":595,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Contrato literal íntegro en el módulo de la pantalla vinculada; aplicación limitada a la superficie fuente."}],"paquete":{"tipo":"NUEVA","codigo":"S22AJ-595-1","clave":"s22aj_legacy_595","familia":"FEATURE_FLAGS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Pantallas consumen beneficios resueltos por configuración y elegibilidad","descripcion":"BLOQUEAR incumplimiento: Las superficies Cliente, B2B/Empresa o de administración que en el futuro muestren o gestionen Beneficios LF no pueden inferir que un beneficio está activo por existir en el diseño o en el código. La visibilidad y disponibilidad se resuelven desde configuración y elegibilidad autoritativas. En Cliente, un beneficio inactivo se oculta o degrada sin dejar espacios rotos. En superficies administrativas o de empresa, la existencia de un control visual no concede permiso ni activa por sí misma el beneficio. Referencias literales del contrato fuente: {\"decision_adr\":\"ADR-LF-BEN-001\",\"applicability_v1\":{\"all\":[],\"any\":[{\"op\":\"IN\",\"path\":[\"target\",\"screen\",\"id\"],\"values\":[5]}],\"status\":\"ACTIVE\",\"provenance\":{\"authority\":\"OWNER_AUTHORIZED_GOVERNED_MIGRATION\",\"r14_event_id\":19951,\"migration_source\":\"LEGACY_POSITIVE_BINDINGS_FOR_EQUIVALENCE_ONLY\",\"decision_event_id\":19948,\"migration_version\":\"20261002173000\"},\"consumer_roles\":[\"INPUT_GOVERNANCE\"],\"schema_version\":\"lf-rule-applicability/v1\"},\"client_render_authority\":\"SERVER_RESOLVED_CONFIG_AND_ELIGIBILITY\",\"inactive_client_behavior\":\"HIDE_OR_GOVERNED_FALLBACK\",\"registered_shells_impacted\":[\"CLIENT_APP_SHELL\",\"B2B_APP_SHELL\"],\"specific_screen_bindings_status\":\"PENDING_SCREEN_BY_SCREEN_REVIEW\",\"screen_mockup_implies_activation\":false,\"unregistered_admin_shell_inferred\":false,\"admin_visual_control_implies_permission\":false}. Binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/595","solicitante":"Cristhian / Claude S22-AJ"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"aj_home_benefit_surface"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"aj_activation_inferred_from_design_or_code"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"aj_visibility_not_authoritative"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_eligibility_not_authoritative"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_inactive_layout_broken"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_visual_control_grants_permission"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_admin_shell_inferred"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aj_visual_control_activates_benefit"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":false,"aj_visibility_not_authoritative":false,"aj_eligibility_not_authoritative":false,"aj_inactive_layout_broken":false,"aj_visual_control_grants_permission":false,"aj_admin_shell_inferred":false,"aj_visual_control_activates_benefit":false,"aj_home_benefit_surface":true},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":true,"aj_visibility_not_authoritative":false,"aj_eligibility_not_authoritative":false,"aj_inactive_layout_broken":false,"aj_visual_control_grants_permission":false,"aj_admin_shell_inferred":false,"aj_visual_control_activates_benefit":false,"aj_home_benefit_surface":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":false,"aj_visibility_not_authoritative":true,"aj_eligibility_not_authoritative":false,"aj_inactive_layout_broken":false,"aj_visual_control_grants_permission":false,"aj_admin_shell_inferred":false,"aj_visual_control_activates_benefit":false,"aj_home_benefit_surface":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":false,"aj_visibility_not_authoritative":false,"aj_eligibility_not_authoritative":true,"aj_inactive_layout_broken":false,"aj_visual_control_grants_permission":false,"aj_admin_shell_inferred":false,"aj_visual_control_activates_benefit":false,"aj_home_benefit_surface":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":false,"aj_visibility_not_authoritative":false,"aj_eligibility_not_authoritative":false,"aj_inactive_layout_broken":true,"aj_visual_control_grants_permission":false,"aj_admin_shell_inferred":false,"aj_visual_control_activates_benefit":false,"aj_home_benefit_surface":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":false,"aj_visibility_not_authoritative":false,"aj_eligibility_not_authoritative":false,"aj_inactive_layout_broken":false,"aj_visual_control_grants_permission":true,"aj_admin_shell_inferred":false,"aj_visual_control_activates_benefit":false,"aj_home_benefit_surface":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":false,"aj_visibility_not_authoritative":false,"aj_eligibility_not_authoritative":false,"aj_inactive_layout_broken":false,"aj_visual_control_grants_permission":false,"aj_admin_shell_inferred":true,"aj_visual_control_activates_benefit":false,"aj_home_benefit_surface":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":false,"aj_visibility_not_authoritative":false,"aj_eligibility_not_authoritative":false,"aj_inactive_layout_broken":false,"aj_visual_control_grants_permission":false,"aj_admin_shell_inferred":false,"aj_visual_control_activates_benefit":true,"aj_home_benefit_surface":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"aj_activation_inferred_from_design_or_code":true,"aj_visibility_not_authoritative":true,"aj_eligibility_not_authoritative":true,"aj_inactive_layout_broken":true,"aj_visual_control_grants_permission":true,"aj_admin_shell_inferred":true,"aj_visual_control_activates_benefit":true,"aj_home_benefit_surface":false},"esperado":false}]},"hash_paquete":"7ed566f3f73bfbbe94c715a4dd07690ff5f8e883e5bb4baad2c79af1e09734ee","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 IF lf_ops.nucleo_param_valor_v1('CLIENT.ONB001_PROGRESS_CURRENT_STEP') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='ONB001_PROGRESS_CURRENT_STEP' AND hecho='aj_progress_step') THEN RAISE EXCEPTION 'S22AJ_PARAM_PREFLIGHT CLIENT.ONB001_PROGRESS_CURRENT_STEP'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.ONB001_PROGRESS_TOTAL_STEPS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='ONB001_PROGRESS_TOTAL_STEPS' AND hecho='aj_progress_total') THEN RAISE EXCEPTION 'S22AJ_PARAM_PREFLIGHT CLIENT.ONB001_PROGRESS_TOTAL_STEPS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.ONB001_PHONE_DIGITS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='ONB001_PHONE_DIGITS' AND hecho='aj_phone_digits') THEN RAISE EXCEPTION 'S22AJ_PARAM_PREFLIGHT CLIENT.ONB001_PHONE_DIGITS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.ONB001_PHONE_PREFIX_DIGIT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='ONB001_PHONE_PREFIX_DIGIT' AND hecho='aj_phone_prefix') THEN RAISE EXCEPTION 'S22AJ_PARAM_PREFLIGHT CLIENT.ONB001_PHONE_PREFIX_DIGIT'; END IF;
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-26 01:07 Lima: Revisado conforme; 568 excluida; juicio V3 independiente');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22AJ_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22AJ_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22AJ_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22AJ_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22AJ_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-26 01:07 Lima'),h,'GPT / Claude S22-AJ independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22AJ_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22AJ_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22AJ_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22AJ_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $aj$;
COMMIT;
